function setting(string $key): string {
    static $cache = null;
    if ($cache === null) {
        $cache = DEFAULT_SETTINGS;
        try { foreach (all('SELECT key, value FROM settings') as $r) $cache[$r['key']] = $r['value']; } catch (Throwable $e) {}
    }
    return (string)($cache[$key] ?? '');
}
function set_setting(string $key, string $value): void {
    q('INSERT INTO settings(key, value) VALUES(?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value', [$key, $value]);
}

/* ---------------------------------------------------------------- helpers */
function h($s): string { return htmlspecialchars((string)$s, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function slugify(string $s): string {
    $s = mb_strtolower(str_replace(['&', 'Ã©', 'Ã‰'], ['and', 'e', 'e'], $s));
    return trim(preg_replace('/[^a-z0-9]+/', '-', $s), '-');
}
function redirect(string $to, int $code = 302): never { header('Location: ' . kt_url($to), true, $code); exit; }
function is_post(): bool { return ($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST'; }
function json_out($data, int $code = 200): never {
    http_response_code($code);
    header('Content-Type: application/json; charset=utf-8');
    echo json_encode($data, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    exit;
}
function start_session(): void {
    if (session_status() === PHP_SESSION_ACTIVE) return;
    session_name('kts');
    session_set_cookie_params(['lifetime' => 60 * 60 * 24 * 30, 'path' => '/', 'httponly' => true, 'samesite' => 'Lax', 'secure' => !empty($_SERVER['HTTPS'])]);
    session_start();
}
function csrf_token(): string {
    start_session();
    if (empty($_SESSION['csrf'])) $_SESSION['csrf'] = bin2hex(random_bytes(16));
    return $_SESSION['csrf'];
}
function csrf_field(): string { return '<input type="hidden" name="csrf" value="' . h(csrf_token()) . '">'; }
function csrf_check(): void {
    start_session();
    $t = $_POST['csrf'] ?? ($_SERVER['HTTP_X_CSRF'] ?? '');
    if (!$t || !hash_equals($_SESSION['csrf'] ?? '', $t)) { http_response_code(419); exit('Your session expired. Go back, refresh the page and try again.'); }
}
function view(string $name, array $vars = []): string {
    ob_start();
    ('view_' . $name)($vars);
    return ob_get_clean();
}

/* ---------------------------------------------------------------- currency */
function rates(): array {
    static $r = null;
    if ($r !== null) return $r;
    $r = json_decode(setting('rates'), true);
    if (!is_array($r) || !$r) $r = ['USD' => 1];
    // keep exchange rates fresh by themselves: at most one quick try an hour once they are a day old
    $upd = strtotime(setting('rates_updated') ?: '2000-01-01');
    $tried = (int)(setting('rates_tried') ?: 0);
    if (PHP_SAPI !== 'cli' && $upd < time() - 86400 && $tried < time() - 3600) {
        set_setting('rates_tried', (string)time());
        $new = fetch_rates(3);
        if ($new) { $r = $new; set_setting('rates', json_encode($new)); set_setting('rates_updated', date('Y-m-d H:i:s')); }
    }
    return $r;
}
function fetch_rates(int $timeout = 10): ?array {
    $raw = http_get('https://open.er-api.com/v6/latest/USD', $timeout);
    $j = $raw ? json_decode($raw, true) : null;
    if (empty($j['rates']['JPY'])) return null;
    $out = ['USD' => 1];
    foreach (['AUD', 'EUR', 'GBP', 'CAD', 'JPY'] as $c) if (isset($j['rates'][$c])) $out[$c] = round((float)$j['rates'][$c], $c === 'JPY' ? 2 : 4);
    return $out;
}
function http_get(string $url, int $timeout = 10): ?string {
    if (function_exists('curl_init')) {
        $ch = curl_init($url);
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER => true, CURLOPT_FOLLOWLOCATION => true, CURLOPT_TIMEOUT => $timeout, CURLOPT_CONNECTTIMEOUT => min(3, $timeout), CURLOPT_USERAGENT => 'Kiratora']);
        $b = curl_exec($ch); $ok = curl_getinfo($ch, CURLINFO_HTTP_CODE) === 200; curl_close($ch);
        return $ok && is_string($b) ? $b : null;
    }
    $b = @file_get_contents($url, false, stream_context_create(['http' => ['timeout' => $timeout, 'header' => "User-Agent: Kiratora\r\n"]]));
    return $b === false ? null : $b;
}
function currency(): string {
    $c = $_COOKIE['cur'] ?? setting('default_currency');
    return isset(rates()[$c]) ? $c : 'USD';
}
function money(?float $usd, ?string $cur = null, bool $code = false): string {
    if ($usd === null) return 'Price on request';
    $cur = $cur ?? currency();
    $v = $usd * (rates()[$cur] ?? 1);
    $sym = ['USD' => '$', 'AUD' => 'A$', 'CAD' => 'C$', 'EUR' => 'â‚¬', 'GBP' => 'Â£', 'JPY' => 'Â¥'][$cur] ?? '';
    $s = $cur === 'JPY' ? number_format(round($v)) : number_format($v, 2);
    return $sym . $s . ($code ? ' ' . $cur : '');
}
// a shop rule set in US dollars, written short: $100, $2,000, $12.50
function money_usd(float $usd): string { return '$' . number_format($usd, floor($usd) == $usd ? 0 : 2); }
// products on show (for "Search 12,900+ products")
function catalog_size(): int { static $n = null; return $n ??= (int)val('SELECT COUNT(*) FROM products WHERE published = 1'); }

/* ---------------------------------------------------------------- pricing ladders */
const SEALED = ['Booster Boxes', 'Booster Box Cases', 'Booster Packs', 'Elite Trainer Boxes', 'Premium & Special Sets', 'Booster & Hobby Boxes', 'Cases', 'Packs', 'Decks, Bundles & Sets'];
function product_kind(array $p): string {
    if (in_array($p['section'], SEALED, true)) return 'sealed';
    if ($p['section'] === 'Single Cards') return 'single';
    if (in_array($p['section'], ['PSA Graded Cards', 'Graded Cards'], true)) return 'graded';
    return 'accessory';
}
/** Returns ['moq'=>int, 'step'=>int, 'tiers'=>[[minQty, unitUsd], ...]] (first tier = base price at moq). */
function ladder(array $p): array {
    $rules = json_decode(setting('pricing_rules'), true) ?: [];
    $kind = product_kind($p);
    $r = $rules[$kind] ?? ['moq' => 1, 'step' => 1, 'breaks' => []];
    $base = $p['price_usd'] === null ? null : (float)$p['price_usd'];
    $moq = $p['moq'] !== null ? (int)$p['moq'] : (int)$r['moq'];
    $step = $p['step'] !== null ? (int)$p['step'] : (int)$r['step'];
    if ($kind === 'sealed' && $p['moq'] === null && $base !== null && isset($r['max_price_for_moq']) && $base > (float)$r['max_price_for_moq']) { $moq = 1; $step = 1; }
    $moq = max(1, $moq); $step = max(1, $step);
    $tiers = [];
    if ($base !== null) {
        $tiers[] = [$moq, $base];
        if (!empty($p['breaks'])) {
            foreach ((json_decode($p['breaks'], true) ?: []) as $b) if ((int)$b[0] > $moq) $tiers[] = [(int)$b[0], (float)$b[1]];
        } else {
            foreach ($r['breaks'] ?? [] as $b) if ((int)$b[0] > $moq) $tiers[] = [(int)$b[0], round($base * (1 - $b[1] / 100), 2)];
        }
    }
    usort($tiers, fn($a, $b) => $a[0] <=> $b[0]);
    return ['moq' => $moq, 'step' => $step, 'tiers' => $tiers];
}
function unit_price(array $lad, int $qty): ?float {
    if (!$lad['tiers']) return null;
    $u = $lad['tiers'][0][1];
    foreach ($lad['tiers'] as [$min, $price]) if ($qty >= $min) $u = $price;
    return $u;
}
function next_tier(array $lad, int $qty): ?array {
    foreach ($lad['tiers'] as $t) if ($t[0] > $qty) return $t;
    return null;
}
function normalize_qty(array $lad, int $qty): int {
    if ($qty <= 0) return 0;
    $qty = max($lad['moq'], $qty);
    $extra = ($qty - $lad['moq']) % $lad['step'];
    return $extra ? $qty + ($lad['step'] - $extra) : $qty;
}

/* ---------------------------------------------------------------- product pages it appears on */
function product_paths(array $p): array {
    $paths = ['/shop'];
    foreach (['section_url', 'set_url', 'game_url'] as $k) if (!empty($p[$k])) $paths[] = $p[$k];
    if ($p['game'] === 'PokÃ©mon') {
        $paths[] = '/pokemon';
        if ($p['language'] === 'Japanese') $paths[] = '/japanese-pokemon-cards';
        if ($p['language'] === 'English') $paths[] = '/english-pokemon-cards';
        if ($p['language'] === 'Chinese') $paths[] = '/chinese-pokemon-cards';
        if ($p['set_url'] && $p['series'] === 'Mega Evolution') $paths[] = '/sets/mega-evolution';
        if ($p['set_url'] && $p['series'] === 'Scarlet & Violet') $paths[] = '/sets/scarlet-violet';
        if ($p['set_url'] && $p['series'] === 'Sword & Shield') $paths[] = '/sets/sword-shield';
    }
    foreach (auto_paths($p) as $x) $paths[] = $x;
    foreach (preg_split('/\s+/', trim($p['also_on'] ?? '')) as $x) if ($x !== '') $paths[] = $x;
    return array_values(array_unique($paths));
}
// PokÃ©mon names that have their own card page (/cards/<name>-pokemon-cards)
const CARD_NAMES = ['charizard', 'pikachu', 'gengar', 'mewtwo', 'mew', 'umbreon', 'eevee', 'charmander', 'snorlax', 'blastoise', 'bulbasaur', 'ditto', 'dragonite', 'greninja', 'arceus'];
// Rule-based pages: every new or imported product lands on these automatically.
function auto_paths(array $p): array {
    $out = [];
    $sec = $p['section'] ?? ''; $title = (string)($p['title'] ?? ''); $name = (string)($p['card_name'] ?? '');
    $isCard = in_array($sec, ['Single Cards', 'PSA Graded Cards', 'Graded Cards'], true);
    if (($p['game'] ?? '') === 'PokÃ©mon') {
        if ($isCard) {
            $hay = $name !== '' ? $name : preg_replace('/Eevee Heroes|Mew Promo/i', '', $title);
            foreach (CARD_NAMES as $n) if (preg_match('/\b' . $n . '\b/i', $hay)) $out[] = "/cards/$n-pokemon-cards";
            if (preg_match('/\bPSA 10\b/', $title)) $out[] = '/cards/psa-10-pokemon-cards';
            if (preg_match('/\bPSA\b/', $title) && $sec !== 'Single Cards') $out[] = '/cards/psa-graded-pokemon-cards';
            if (preg_match('/TAG TEAM/i', $title) || preg_match('/&.*\bGX\b/', $name)) $out[] = '/cards/tag-team-pokemon-cards';
        }
        if ($sec === 'Single Cards') {
            $rar = (string)($p['rarity'] ?? ''); $set = (string)($p['set_name'] ?? '');
            if (preg_match('/\bex\b/', $name)) $out[] = '/cards/ex-pokemon-cards';
            if (preg_match('/^Mega\s/', $name)) $out[] = '/cards/mega-pokemon-cards';
            if (str_contains($rar, 'Shiny') || str_contains($set, 'Shiny Vault') || str_contains($set, 'Shiny Treasure')) $out[] = '/cards/shiny-pokemon-cards';
            if (stripos((string)($p['variant'] ?? ''), 'holo') !== false) $out[] = '/cards/holo-pokemon-cards';
            if ($rar === 'Ultra Rare') $out[] = '/cards/ultra-rare-pokemon-cards';
            if (preg_match('/\bEnergy\b/', $name)) $out[] = '/cards/energy-pokemon-cards';
            elseif (is_trainer_card($p)) $out[] = '/cards/trainer-pokemon-cards';
            if (($p['subsection'] ?? '') === 'Jumbo cards') $out[] = '/cards/jumbo-pokemon-cards';
        }
        if (in_array($sec, ['Premium & Special Sets', 'Decks, Bundles & Sets'], true) && preg_match('/\bdecks?\b/i', $title) && !preg_match('/sleeve|deck box/i', $title)) $out[] = '/pokemon-decks';
    }
    if ($sec === 'Accessories') {
        $sub = (string)($p['subsection'] ?? '');
        if ($sub === 'Sleeves' || preg_match('/sleeve/i', $title)) $out[] = '/accessories/card-sleeves';
        if ($sub === 'Top loaders & cases' || preg_match('/top ?loader|one.?touch|card saver|magnetic/i', $title)) $out[] = '/accessories/toploaders';
        if ($sub === 'Card binders' || preg_match('/binder/i', $title)) $out[] = '/accessories/card-binders';
    }
    return $out;
}
// Trainer cards (Supporter, Item, Stadium, Tool) have no PokÃ©mon type in the data.
function is_trainer_card(array $p): bool {
    if (($p['game'] ?? '') !== 'PokÃ©mon' || ($p['section'] ?? '') !== 'Single Cards' || ($p['card_type'] ?? '') !== '') return false;
    $rar = (string)($p['rarity'] ?? ''); $name = (string)($p['card_name'] ?? '');
    if ($rar === '' || $rar === 'Promo' || ($p['set_name'] ?? '') === '' || $name === '') return false;
    return !preg_match('/\b(ex|EX|V|VMAX|VSTAR|GX|V-UNION|BREAK|LV\.X|Prime)\b|Energy|Japanese \d|\d+\/\d+/', $name);
}
function sync_product_paths(int $id): void {
    $p = one('SELECT * FROM products WHERE id = ?', [$id]);
    q('DELETE FROM product_paths WHERE product_id = ?', [$id]);
    if (!$p) return;
    $ins = db()->prepare('INSERT OR IGNORE INTO product_paths(product_id, path) VALUES(?, ?)');
    foreach (product_paths($p) as $path) $ins->execute([$id, $path]);
}
// A photo now saved on this server. A product of the shop's own has no supplier to copy from again, so it also stops
// pointing at the address the photo came from; supplier (Card Bot) products keep theirs, so a lost copy can be fetched again.
function photo_saved(int $id, string $file): void {
    q("UPDATE products SET image_local = ?, image_url = CASE WHEN source = 'cardbot' THEN image_url ELSE ? END WHERE id = ?", [$file, '/' . $file, $id]);
}
function product_image(array $p): string {
    if (!empty($p['image_local']) && $p['image_local'] !== '!') return '/' . ltrim($p['image_local'], '/');
    if (($p['image_local'] ?? '') === '!' || empty($p['image_url'])) return (string)($p['image_url'] ?? '');
    // served from kiratora.com: the first request copies the photo onto the server (see serve_product_image)
    return '/img/' . $p['handle'];
}
// /img/<handle>.jpg â€” copy the supplier photo onto this server the first time anyone (or Google) asks for it, then serve it from here.
function serve_product_image(string $handle): never {
    $p = one('SELECT id, handle, image_url, image_local FROM products WHERE handle = ?', [$handle]);
    if (!$p || $p['image_url'] === '') { http_response_code(404); exit; }
    $local = $p['image_local'] !== '' && $p['image_local'] !== '!' ? ROOT . '/' . ltrim($p['image_local'], '/') : null;
    $down = (int)(setting('img_down_until') ?: 0) > time();   // the server could not reach photo hosts a moment ago: don't make visitors wait
    if (!$down && (!$local || !is_file($local)) && $p['image_local'] !== '!' && preg_match('#^https?://#', $p['image_url'])) {
        $dir = ROOT . '/uploads/products';
        if (!is_dir($dir)) @mkdir($dir, 0775, true);
        $data = false;
        if (function_exists('curl_init')) {
            $ch = curl_init($p['image_url']);
            curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER => true, CURLOPT_FOLLOWLOCATION => true, CURLOPT_MAXREDIRS => 3, CURLOPT_TIMEOUT => 8, CURLOPT_CONNECTTIMEOUT => 4, CURLOPT_USERAGENT => 'Kiratora image copier']);
            $data = curl_exec($ch);
            $code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
            if ($code !== 200) $data = false;
            if ($code === 0) set_setting('img_down_until', (string)(time() + 600));   // network blocked or timed out: try again in 10 minutes
            if ($code === 404 || $code === 410) q("UPDATE products SET image_local = '!' WHERE id = ?", [$p['id']]);
            curl_close($ch);
        } else {
            $data = @file_get_contents($p['image_url'], false, stream_context_create(['http' => ['timeout' => 12, 'header' => "User-Agent: Kiratora image copier\r\n"]]));
        }
        $info = $data ? @getimagesizefromstring($data) : false;
        $ext = ['image/jpeg' => 'jpg', 'image/png' => 'png', 'image/webp' => 'webp', 'image/gif' => 'gif'][$info['mime'] ?? ''] ?? null;
        if ($ext && strlen($data) < 8_000_000) {
            $file = substr($p['handle'], 0, 120) . '.' . $ext;
            if (@file_put_contents("$dir/$file", $data) !== false) {
                photo_saved((int)$p['id'], "uploads/products/$file");
                $local = "$dir/$file";
            }
        }
    }
    if ($local && is_file($local)) {
        $mime = ['jpg' => 'image/jpeg', 'jpeg' => 'image/jpeg', 'png' => 'image/png', 'webp' => 'image/webp', 'gif' => 'image/gif'][strtolower(pathinfo($local, PATHINFO_EXTENSION))] ?? 'image/jpeg';
        header('Content-Type: ' . $mime);
        header('Cache-Control: public, max-age=31536000, immutable');
        header('Content-Length: ' . filesize($local));
        readfile($local);
        exit;
    }
    // could not copy right now: send the visitor to the original photo and try again next time
    header('Cache-Control: no-store');
    redirect($p['image_url'], 302);
}

/* ---------------------------------------------------------------- cart (session) */
function cart(): array { start_session(); return $_SESSION['cart'] ?? []; }
function cart_set(int $id, int $qty): void {
    start_session();
    $p = one('SELECT * FROM products WHERE id = ? AND published = 1', [$id]);
    if (!$p || !$p['in_stock'] || $p['price_usd'] === null) { unset($_SESSION['cart'][$id]); return; }
    $qty = normalize_qty(ladder($p), $qty);
    if ($qty <= 0) unset($_SESSION['cart'][$id]); else $_SESSION['cart'][$id] = $qty;
}
function cart_lines(): array {
    $c = cart();
    if (!$c) return [];
    $ids = implode(',', array_map('intval', array_keys($c)));
    $rows = all("SELECT * FROM products WHERE id IN ($ids)");
    $lines = [];
    foreach ($rows as $p) {
        $qty = (int)$c[$p['id']];
        $lad = ladder($p);
        $unit = unit_price($lad, $qty);
        $lines[] = ['p' => $p, 'qty' => $qty, 'ladder' => $lad, 'unit' => $unit, 'line' => round($unit * $qty, 2), 'next' => next_tier($lad, $qty)];
    }
    return $lines;
}
function cart_summary(): array {
    $lines = cart_lines();
    $sub = 0; $count = 0;
    foreach ($lines as $l) { $sub += $l['line']; $count += $l['qty']; }
    return ['lines' => $lines, 'subtotal' => round($sub, 2), 'count' => $count, 'items' => count($lines)];
}
/* ---------------------------------------------------------------- shipping */
// zone => [standard flat, standard per kg, express flat, express per kg] in USD
function shipping_zones(): array {
    $z = json_decode(setting('shipping_zones'), true);
    return is_array($z) && $z ? $z : json_decode(DEFAULT_SETTINGS['shipping_zones'], true);
}
const EUROPE = ['Germany', 'France', 'Netherlands', 'Belgium', 'Spain', 'Italy', 'Sweden', 'Norway', 'Denmark', 'Finland', 'Ireland', 'Switzerland', 'Austria', 'Poland', 'Portugal', 'Czech Republic', 'Greece', 'Hungary', 'Romania', 'Luxembourg'];
const ASIA_PACIFIC = ['Australia', 'New Zealand', 'Singapore', 'Hong Kong', 'Taiwan', 'South Korea', 'Malaysia', 'Philippines', 'Thailand', 'Indonesia', 'Vietnam', 'China'];
function shipping_zone(string $country): string {
    return match (true) {
        $country === 'United States' => 'United States', $country === 'Canada' => 'Canada', $country === 'United Kingdom' => 'United Kingdom',
        $country === 'Japan' => 'Japan', in_array($country, EUROPE, true) => 'Europe', in_array($country, ASIA_PACIFIC, true) => 'Asia-Pacific',
        default => 'Rest of world',
    };
}
// packed weight in kg (sealed booster box about 0.4 kg, Elite Trainer Box about 0.9 kg)
function product_weight(array $p): float {
    if (!empty($p['weight_kg'])) return (float)$p['weight_kg'];
    $t = mb_strtolower((string)$p['title']); $sec = (string)$p['section'];
    $n = preg_match('/\((\d+)[ -]?ct\)|\b(\d+)[ -]?ct\b/', $t, $m) ? (int)($m[1] ?: $m[2]) : 0;
    return match (true) {
        in_array($sec, ['Booster Box Cases', 'Cases'], true) => max(1, $n ?: 6) * (str_contains($t, 'elite trainer') ? 0.9 : 0.4),
        $sec === 'Elite Trainer Boxes' || str_contains($t, 'elite trainer') || str_contains($t, 'premium trainer') => 0.9,
        in_array($sec, ['Booster Boxes', 'Booster & Hobby Boxes'], true) => 0.4,
        in_array($sec, ['Booster Packs', 'Packs'], true) => 0.03,
        $sec === 'Single Cards' => ($p['subsection'] ?? '') === 'Jumbo cards' ? 0.1 : 0.02,
        in_array($sec, ['PSA Graded Cards', 'Graded Cards'], true) => 0.15,
        $sec === 'Accessories' => str_contains($t, 'binder') ? 0.6 : (str_contains($t, 'playmat') ? 0.4 : 0.1),
        default => 0.5,
    };
}
function cart_weight(array $lines): float {
    $w = 0.0; foreach ($lines as $l) $w += product_weight($l['p']) * $l['qty'];
    return round($w, 3);
}
function shipping_rate(string $country, string $method, float $kg): float {
    $z = shipping_zones()[shipping_zone($country)] ?? shipping_zones()['Rest of world'];
    $cost = $method === 'express' ? $z[2] + $z[3] * $kg : $z[0] + $z[1] * $kg;
    return (float)ceil(round($cost, 4));   // rounded up to the next whole dollar
}
// Free Standard shipping over the threshold; Express on a free-shipping order costs only the difference.
function shipping_cost(float $subtotal, string $method, string $country = 'United States', float $kg = 0.0): float {
    $std = shipping_rate($country, 'standard', $kg);
    $free = $subtotal >= (float)setting('free_shipping_over_usd');
    if ($method !== 'express') return $free ? 0.0 : $std;
    $exp = shipping_rate($country, 'express', $kg);
    return $free ? max(0.0, $exp - $std) : $exp;
}

