// one header style for every homepage section: small label, title, a line of context and a "see all" button
function hp_head(string $eyebrow, string $title, string $desc, string $url = '', string $link = '', string $id = ''): void {
    echo '<div class="hp-head"><div class="hp-head-text"><p class="hp-eyebrow">' . h($eyebrow) . '</p><h2 class="h2"' . ($id !== '' ? ' id="' . h($id) . '"' : '') . '>' . h($title) . '</h2>'
       . ($desc !== '' ? '<p class="hp-desc">' . h($desc) . '</p>' : '') . '</div>'
       . ($url !== '' ? '<a class="hp-more" href="' . h($url) . '">' . h($link) . '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3 8h10M9 4l4 4-4 4"/></svg></a>' : '') . '</div>';
}

function view_home(array $__vars): void { extract($__vars, EXTR_SKIP); ?><?php
$free = money((float)setting('free_shipping_over_usd'));
$quick = [['Umbreon', '/cards/umbreon-pokemon-cards'], ['Charizard', '/cards/charizard-pokemon-cards'], ['Gengar', '/cards/gengar-pokemon-cards'], ['30th Celebration', '/sets/30th-celebration'], ['151', '/sets/151'], ['Gold cards', '/cards/gold-pokemon-cards'], ['Booster boxes', '/booster-boxes']];
$steps = [['1', 'Browse with prices in view', 'Minimums, case steps and the price at each quantity are on every listing. No account, no quote requests.'],
          ['2', 'Reserve your items', 'Add a delivery address and pick how to pay, and we hold your items for ' . (int)setting('hold_hours') . ' hours.'],
          ['3', 'Pay how you like', 'Bitcoin right away with a QR code, or ETH, USDT, Cash App, Apple Pay and others through your invoice.'],
          ['4', 'On its way from Japan', 'Carefully packed and handed to EMS, DHL or FedEx within 48 hours. Most US orders arrive in 3â€“6 working days.']];
// cards for the 3D ring: the featured set's best singles with a photo, one per name
$ring = []; $seen = [];
foreach ($show['chase'] ?? [] as $c) {
    $n = d_clean_name($c); if (isset($seen[$n])) continue; $seen[$n] = 1;
    $lad = $c['price_usd'] !== null ? ladder($c) : null;
    $ring[] = ['img' => product_image($c), 'name' => $n, 'price' => $lad ? money($lad['tiers'][0][1]) : '', 'url' => '/products/' . $c['handle']];
    if (count($ring) === 7) break;
}
if (count($ring) < 5) foreach ($singles as $c) { $n = d_clean_name($c); if (isset($seen[$n])) continue; $seen[$n] = 1; $lad = ladder($c);
    $ring[] = ['img' => product_image($c), 'name' => $n, 'price' => money($lad['tiers'][0][1]), 'url' => '/products/' . $c['handle']]; if (count($ring) === 7) break; }
$setName = $show['set']['title'] ?? ''; $clean = preg_replace('/\s*\(.*\)$/', '', $setName);
// the chase-card galaxy: in-stock singles with a photo, one per name
$galaxy = []; $gseen = [];
foreach ($singles as $c) { $n = d_clean_name($c); if (isset($gseen[$n])) continue; $gseen[$n] = 1; $lad = ladder($c);
    $galaxy[] = ['img' => product_image($c), 'name' => $n, 'price' => money($lad['tiers'][0][1]), 'url' => '/products/' . $c['handle'], 'set' => $c['set_name'], 'p' => $c]; if (count($galaxy) === 16) break; }
// photos that drift past in the sky: sealed boxes, category photos and more singles
$float = []; $fseen = [];
foreach ($featured as $c) { $u = product_image($c); if (isset($fseen[$u])) continue; $fseen[$u] = 1; $float[] = ['img' => $u, 'kind' => 'box']; }
foreach ($cats as $c) if (!empty($c['img']) && !isset($fseen[$c['img']])) { $fseen[$c['img']] = 1; $float[] = ['img' => $c['img'], 'kind' => 'box']; }
foreach ($singles as $c) { $u = product_image($c); if (isset($fseen[$u])) continue; $fseen[$u] = 1; $float[] = ['img' => $u, 'kind' => 'card']; }
usort($float, fn($a, $b) => crc32($a['img']) <=> crc32($b['img']));
// the featured product shown as a real 3D box (built from its photo) when the 30th Celebration ETB photo is the homepage photo
$box = null;
if (setting('hero_image') === '/assets/img/30th-celebration-etb.jpg' && ($bp = one("SELECT * FROM products WHERE handle = '30th-celebration-elite-trainer-box' AND published = 1"))) {
    $bl = $bp['price_usd'] !== null ? ladder($bp) : null;
    $box = ['front' => '/assets/img/etb-front.webp?v=1', 'side' => '/assets/img/etb-side.webp?v=1', 'name' => '30th Celebration PokÃ©mon Center Elite Trainer Box', 'price' => $bl ? 'from ' . money($bl['tiers'][0][1]) : '', 'url' => '/products/' . $bp['handle']];
}
?>
