        <?php $from = max(1, $page - 2); $to = min($pages, $page + 2);
        if ($from > 1) echo '<a href="' . h(listing_url($base, $params, ['page' => 1])) . '">1</a>' . ($from > 2 ? '<span>â€¦</span>' : '');
