.ftr{background:#F7F3EA;border-top:1px solid #EADFC4}
.ftr a{color:#2A251D}.ftr a:hover{color:#8C6A1C}
.toast{background:#1B1813;color:#FFFFFF}
.badge{background:#1B1813;color:#FFFFFF}
.drawer{background:#FFFFFF}

/* dark text on every gold surface */
.order-btn,.order-btn:hover,.hs-badge,.sc-new,.feature-kicker,.pcol .note,.pager span[aria-current],.skip{color:#1B1813!important}
.order-btn [data-cart-count],.order-btn .count{background:#1B1813;color:#FFFFFF}
.cur summary{background:#FFFFFF;border:1px solid #D9CFB8;color:#1B1813}
.cur-list{background:#FFFFFF;border-color:#ECE5D5}

/* small gold text dark enough to read on white */
.hp-eyebrow,.bar a,.bar{color:#6E5312}
.hp-eyebrow::before{background:#B8912F}

:root{--shu:#8C6A1C;--ai:#7A5C17;--kin:#7A5C17}
:root{--matcha:#1E7A45;--matcha-soft:#E6F4EA;--danger:#B42335;--danger-soft:#FBE9EC}
