/* Kiratora storefront */
(() => {
  const $ = (s, el = document) => el.querySelector(s);
  const $$ = (s, el = document) => [...el.querySelectorAll(s)];
  const KTS = window.KTS || {};
  // site addresses that work on any server: in a sub-folder, or without URL rewriting (index.php?r=/path)
  const KT = window.KT || {base: '', pretty: 1, path: location.pathname};
  const U = u => {
    if (typeof u !== 'string' || u.charAt(0) !== '/' || u.charAt(1) === '/') return u;
    if (u.startsWith('/index.php?') || (KT.base && (u === KT.base || u.startsWith(KT.base + '/')))) return u;
    if (KT.pretty || u.startsWith('/uploads/') || u.startsWith('/assets/')) return KT.base + u;
    let frag = ''; const h = u.indexOf('#'); if (h >= 0) { frag = u.slice(h); u = u.slice(0, h); }
    const i = u.indexOf('?');
    return KT.base + '/index.php?r=' + (i >= 0 ? u.slice(0, i) + '&' + u.slice(i + 1) : u) + frag;
  };
  // first visit on a new server: check once whether clean addresses (/shop) reach the shop
  if (!KT.pretty) fetch(KT.base + '/kiratora-url-check', {cache: 'no-store'}).catch(() => {});
  const fmt = usd => {
    const v = usd * (KTS.rate || 1);
    return (KTS.sym || '$') + (KTS.cur === 'JPY' ? Math.round(v).toLocaleString('en-US') : v.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2}));
  };
