      const spot = new T.Mesh(new T.PlaneGeometry(4.6, 9), new T.MeshBasicMaterial({map: BEAM, transparent: true, opacity: .22, depthWrite: false, blending: T.AdditiveBlending})); spot.position.set(0, 2.6, -1.2); spot.visible = !LIGHT; sc.add(spot);
