      let cur = 0, target = 0, last = performance.now(), hold = false;
      const cap = vaultEl.querySelector('[data-vault-caption]');
      const setCaption = () => {
        const i = ((Math.round(target) % items.length) + items.length) % items.length, c = items[i];
